<!-- wp:wdl/lw-pr-custom-title-14 {"subTitle":"REAL VOICES","mainTitle":"聞きにくいことほど、先に","headingLevel":2,"colorMain":"#3d6b52","borderRadius":6,"maxWidth":0} -->
<div class="wp-block-wdl-lw-pr-custom-title-14 lw-pr-custom-title-14" style="--color-main:#3d6b52;width:100%;--custom-title-14-border-radius:6px"><h2 class="ttl"><span class="sub"><span class="text">REAL VOICES</span></span><span class="main">聞きにくいことほど、先に</span></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-14 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#2c332e;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">面談でいちばん多くいただくご質問です。<span class="lw-br on_500px"></span>答えにくいことも、そのまま書いています。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-qa-2 {"maxWidth":900,"qImageBorderColor":"#3d6b52","qTextBg":"#eef4f0","aImageBorderColor":"#3d6b52","qTextColor":"#1f3f2f","qTextFontSizePc":20,"qTextFontSizeSp":16} -->
<div class="wp-block-wdl-lw-pr-qa-2 lw-pr-qa-2" style="--qa-2-max-w:900px;--qa-2-dt-image-bd-color:#3d6b52;--qa-2-dt-text-bg:#eef4f0;--qa-2-dt-text-color:#1f3f2f;--qa-2-dt-text-fontsize-pc:20px;--qa-2-dt-text-fontsize-sp:16px;--qa-2-dd-image-bd-color:#3d6b52"><dl class="lw-pr-qa-2__wrap"><!-- wp:wdl/lw-pr-qa-2-item {"qImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_01.webp","qText":"うちの子、集中力が続かないのですが。","aImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_01.webp"} -->
<div class="wp-block-wdl-lw-pr-qa-2-item lw-pr-qa-2__wrap__inner"><dt class="lw-pr-qa-2__q_wrap"><div class="lw-pr-qa-2__q_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_01.webp" alt=""/></div><div class="lw-pr-qa-2__q_text"><p class="text">うちの子、集中力が続かないのですが。</p></div></dt><dd class="lw-pr-qa-2__a_wrap"><div class="lw-pr-qa-2__a_text"><!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">90分をまるごと座らせる授業はしていません。25分ごとに区切って、あいだに立ってもらいます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">それでも難しいお子さんには、机の向きを変える・書く量を減らす、といった調整をします。「続かない」を直そうとはしません。<strong>続かなくても進む形</strong>を先に作ります。</p>
<!-- /wp:paragraph --></div><div class="lw-pr-qa-2__a_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_01.webp" alt=""/></div></dd></div>
<!-- /wp:wdl/lw-pr-qa-2-item -->
<!-- wp:wdl/lw-pr-qa-2-item {"qImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_02.webp","qText":"成績が下がったら、やめるべきですか。","aImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_01.webp"} -->
<div class="wp-block-wdl-lw-pr-qa-2-item lw-pr-qa-2__wrap__inner"><dt class="lw-pr-qa-2__q_wrap"><div class="lw-pr-qa-2__q_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_02.webp" alt=""/></div><div class="lw-pr-qa-2__q_text"><p class="text">成績が下がったら、やめるべきですか。</p></div></dt><dd class="lw-pr-qa-2__a_wrap"><div class="lw-pr-qa-2__a_text"><!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">すぐにはお勧めしません。塾を替えた直後は、どこでも1〜2か月は下がります。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">ただし3か月見て変わらなければ、こちらから「合っていないかもしれません」とお伝えします。引き止めることはありません。</p>
<!-- /wp:paragraph --></div><div class="lw-pr-qa-2__a_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_01.webp" alt=""/></div></dd></div>
<!-- /wp:wdl/lw-pr-qa-2-item -->
<!-- wp:wdl/lw-pr-qa-2-item {"qImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_03.webp","qText":"正直、月謝が高いと感じています。","aImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_02.webp"} -->
<div class="wp-block-wdl-lw-pr-qa-2-item lw-pr-qa-2__wrap__inner"><dt class="lw-pr-qa-2__q_wrap"><div class="lw-pr-qa-2__q_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_03.webp" alt=""/></div><div class="lw-pr-qa-2__q_text"><p class="text">正直、月謝が高いと感じています。</p></div></dt><dd class="lw-pr-qa-2__a_wrap"><div class="lw-pr-qa-2__a_text"><!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">そう感じられるのは当然だと思います。金額は下げられませんが、<strong>減らせる科目</strong>のご相談はできます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">得意な科目を1つ外して、苦手な科目に寄せるだけで月謝が下がった方もいらっしゃいます。「全科目そろえたほうがいい」とは申しません。</p>
<!-- /wp:paragraph --></div><div class="lw-pr-qa-2__a_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_02.webp" alt=""/></div></dd></div>
<!-- /wp:wdl/lw-pr-qa-2-item -->
<!-- wp:wdl/lw-pr-qa-2-item {"qImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_01.webp","qText":"無理に通わせても意味がないのでは。","aImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_02.webp"} -->
<div class="wp-block-wdl-lw-pr-qa-2-item lw-pr-qa-2__wrap__inner"><dt class="lw-pr-qa-2__q_wrap"><div class="lw-pr-qa-2__q_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_01.webp" alt=""/></div><div class="lw-pr-qa-2__q_text"><p class="text">無理に通わせても意味がないのでは。</p></div></dt><dd class="lw-pr-qa-2__a_wrap"><div class="lw-pr-qa-2__a_text"><!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">「行きたくない」と言っているうちは、成績のためよりも<strong>居場所のため</strong>に来ていただくつもりで見ます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">勉強の話をしない日があってもよいことにしています。まず来られるようになってから、中身を考えます。</p>
<!-- /wp:paragraph --></div><div class="lw-pr-qa-2__a_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_02.webp" alt=""/></div></dd></div>
<!-- /wp:wdl/lw-pr-qa-2-item -->
<!-- wp:wdl/lw-pr-qa-2-item {"qImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_02.webp","qText":"面談は毎回行かないといけませんか。","aImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_03.webp"} -->
<div class="wp-block-wdl-lw-pr-qa-2-item lw-pr-qa-2__wrap__inner"><dt class="lw-pr-qa-2__q_wrap"><div class="lw-pr-qa-2__q_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_02.webp" alt=""/></div><div class="lw-pr-qa-2__q_text"><p class="text">面談は毎回行かないといけませんか。</p></div></dt><dd class="lw-pr-qa-2__a_wrap"><div class="lw-pr-qa-2__a_text"><!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">年2回だけ、必ずお願いしています。それ以外は任意です。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">お仕事の都合がつかない場合は、電話でも、書面でのご報告でも構いません。来られないことで不利になることはありません。</p>
<!-- /wp:paragraph --></div><div class="lw-pr-qa-2__a_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_03.webp" alt=""/></div></dd></div>
<!-- /wp:wdl/lw-pr-qa-2-item -->
<!-- wp:wdl/lw-pr-qa-2-item {"qImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_03.webp","qText":"受験しない子でも通えますか。","aImage":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_03.webp"} -->
<div class="wp-block-wdl-lw-pr-qa-2-item lw-pr-qa-2__wrap__inner"><dt class="lw-pr-qa-2__q_wrap"><div class="lw-pr-qa-2__q_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/qa_q_03.webp" alt=""/></div><div class="lw-pr-qa-2__q_text"><p class="text">受験しない子でも通えますか。</p></div></dt><dd class="lw-pr-qa-2__a_wrap"><div class="lw-pr-qa-2__a_text"><!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">通っている子の半分は受験しません。学校の授業についていくためだけに来ている子も多いです。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"15.5px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#2c332e;font-size:15.5px;line-height:1.9">受験のご案内をこちらからすることはありません。ご希望があったときだけお話しします。</p>
<!-- /wp:paragraph --></div><div class="lw-pr-qa-2__a_image"><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/sk_teacher_03.webp" alt=""/></div></dd></div>
<!-- /wp:wdl/lw-pr-qa-2-item --></dl></div>
<!-- /wp:wdl/lw-pr-qa-2 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-custom-title-14 {"subTitle":"INTERVIEW","mainTitle":"面談でうかがうこと","headingLevel":2,"colorMain":"#3d6b52","borderRadius":6,"maxWidth":0} -->
<div class="wp-block-wdl-lw-pr-custom-title-14 lw-pr-custom-title-14" style="--color-main:#3d6b52;width:100%;--custom-title-14-border-radius:6px"><h2 class="ttl"><span class="sub"><span class="text">INTERVIEW</span></span><span class="main">面談でうかがうこと</span></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-14 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#2c332e;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">この4つだけです。答えにくいことは飛ばして構いません。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/paid-block-lw-company-3 {"dtBackgroundColor":"#2c4d3b","borderColor":"#d8e3da","ddTextColor":"#2c332e","spFullDt":true,"maxWidth":1040} -->
<div class="wp-block-wdl-paid-block-lw-company-3 paid-block-lw-company-3 font_size_m"><dl class="lw-company-3__inner" style="max-width:1040px;line-height:1.6"><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:#2c4d3b"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.6">いま困っていること</div><div class="lw-company-3__dt_arrow" style="background:#2c4d3b"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="color:#2c332e;border-color:#d8e3da;line-height:1.6">成績のことでも、生活のことでも構いません。「特にない」でも大丈夫です。</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:#2c4d3b"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.6">ご家庭の予算</div><div class="lw-company-3__dt_arrow" style="background:#2c4d3b"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="color:#2c332e;border-color:#d8e3da;line-height:1.6">月にいくらまでなら続けられるか。金額から科目を決めます。逆はしません。</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:#2c4d3b"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.6">帰りの時間</div><div class="lw-company-3__dt_arrow" style="background:#2c4d3b"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="color:#2c332e;border-color:#d8e3da;line-height:1.6">何時までに帰す必要があるか。送り迎えの都合も含めて教えてください。</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:#2c4d3b"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.6">やめる基準</div><div class="lw-company-3__dt_arrow" style="background:#2c4d3b"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="color:#2c332e;border-color:#d8e3da;line-height:1.6">どうなったらやめるか。最初に決めておくと、続けるかどうかで迷わなくなります。</dd></div></dl></div>
<!-- /wp:wdl/paid-block-lw-company-3 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-bg-1 {"backgroundType":"image","imagePc":"","imageSp":"","isFullWidth":true,"maxWidth":1040,"minHeightPc":"min-h-pc-150px","minHeightTb":"min-h-tb-160px","minHeightSp":"min-h-sp-160px","innerPaddingTopPc":80,"innerPaddingBottomPc":80,"innerPaddingLeftPc":40,"innerPaddingRightPc":40,"innerPaddingTopTb":64,"innerPaddingBottomTb":64,"innerPaddingLeftTb":32,"innerPaddingRightTb":32,"innerPaddingTopSp":48,"innerPaddingBottomSp":48,"innerPaddingLeftSp":20,"innerPaddingRightSp":20,"filterTypePc":"solid","filterColorPc":"#eef4f0","opacityPc":1,"filterTypeTb":"solid","filterColorTb":"#eef4f0","opacityTb":1,"filterTypeSp":"solid","filterColorSp":"#eef4f0","opacitySp":1} -->
<div class="wp-block-wdl-lw-bg-1 lw-bg-1 min-h-pc-150px min-h-tb-160px min-h-sp-160px bg_all" style="--lw-bg-color-filter-pc:#eef4f0;--lw-bg-opacity-pc:1;--lw-bg-color-filter-tb:#eef4f0;--lw-bg-opacity-tb:1;--lw-bg-color-filter-sp:#eef4f0;--lw-bg-opacity-sp:1;--lw-bg-position-pc:50% 50%;--lw-bg-position-sp:50% 50%;--lw-bg-wrap-centering-pc:center;--lw-bg-wrap-align-pc:center;--lw-bg-wrap-centering-tb:center;--lw-bg-wrap-align-tb:center;--lw-bg-wrap-centering-sp:center;--lw-bg-wrap-align-sp:center"><div class="lw-bg-1-wrap" style="--lw-bg-padding-top-pc:80px;--lw-bg-padding-bottom-pc:80px;--lw-bg-padding-left-pc:40px;--lw-bg-padding-right-pc:40px;--lw-bg-padding-top-tb:64px;--lw-bg-padding-bottom-tb:64px;--lw-bg-padding-left-tb:32px;--lw-bg-padding-right-tb:32px;--lw-bg-padding-top-sp:48px;--lw-bg-padding-bottom-sp:48px;--lw-bg-padding-left-sp:20px;--lw-bg-padding-right-sp:20px;--lw-bg-max-width:1040px"><!-- wp:heading {"level":3,"style":{"color":{"text":"#1f3f2f"},"typography":{"fontSize":"24px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"center"} -->
<h3 class="has-text-align-center has-text-color" style="color:#1f3f2f;font-size:24px;line-height:1.6;margin-top:0px;margin-bottom:16px">まず1回、座ってみてください</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#2c332e"},"typography":{"fontSize":"16px","lineHeight":"1.9"}},"align":"center"} -->
<p class="has-text-align-center has-text-color" style="color:#2c332e;font-size:16px;line-height:1.9">体験授業は無料です。その日のうちに決めていただく必要はありません。</p>
<!-- /wp:paragraph -->
